from openpyxl import load_workbook
from openpyxl.utils import get_column_letter

# Load the workbook and select the active sheet
wb = load_workbook('input.xlsx')
ws = wb['Sheet1']

# Find the row with 'BR1 Sales' in Column C
br1_sales_row = None
for row in ws.iter_rows(min_col=3, max_col=3):
    if row[0].value == 'BR1 Sales':
        br1_sales_row = row[0].row
        break

# If 'BR1 Sales' is found, calculate the sum of values in Column D where Column E is 0
if br1_sales_row:
    sum_d = 0
    for row in ws.iter_rows(min_col=4, max_col=4):
        if ws[row[0].row][4].value == 0:
            sum_d += ws[row[0].row][3].value

    # Insert the sum into Column D next to 'BR1 Sales'
    ws[f'D{br1_sales_row}'] = sum_d

# Identify rows to delete: rows where Column E is 0, except those with 'BR1 Sales' in Column C
rows_to_delete = []
for row in ws.iter_rows(min_col=5, max_col=5):
    if ws[row[0].row][4].value == 0:
        if ws[row[0].row][2].value != 'BR1 Sales':
            rows_to_delete.append(row[0].row)

# Delete the identified rows
for row in sorted(rows_to_delete, reverse=True):
    ws.delete_rows(row)

# Delete blank lines (rows with all empty cells)
blank_rows = []
for row in ws.iter_rows(min_row=1, max_row=ws.max_row):
    if all(cell.value is None for cell in row):
        blank_rows.append(row[0].row)

for row in sorted(blank_rows, reverse=True):
    ws.delete_rows(row)

# Save the modified workbook
wb.save('output.xlsx')
