from openpyxl import load_workbook

# Load the workbook
wb = load_workbook('input.xlsx')
input_sheet = wb['Input']
output_sheet = wb['Output']

# Clear existing data in Output sheet (except headers)
for row in output_sheet.iter_rows(min_row=2, max_row=output_sheet.max_row):
    for cell in row:
        cell.value = None

# Process each row in the Input sheet
for row in input_sheet.iter_rows(min_row=2, values_only=True):
    wtype_id, name, status, filter_str = row

    # Initialize output row
    output_row = [wtype_id, name, status, None, None, None, None]

    # Parse filter string
    if filter_str:
        # Split by ' AND ' to get individual conditions
        conditions = filter_str.split(' AND ')
        for condition in conditions:
            if '"orgId" = "LIM"' in condition:
                output_row[3] = 'LIM'
            elif '"orgId" = "OMG"' in condition:
                output_row[3] = 'OMG'
            elif '"careType" = "AMS' in condition:
                output_row[4] = 'AMS'
            elif '"careType" = "AMSTER"' in condition:
                output_row[4] = 'AMSTER'
            elif '"loc" IN LI' in condition:
                output_row[4] = 'AMSTER'
            elif '"specialtyId" = "66"' in condition:
                output_row[5] = '66'
            elif '"specialtyId" = "77"' in condition:
                output_row[5] = '77'
            elif '"contextId" = "55"' in condition:
                output_row[6] = '55'
            elif '"contextId" = "689"' in condition:
                output_row[6] = '689'
            elif '"contextId" = "213"' in condition:
                output_row[6] = '213'

    # Write the output row to the Output sheet
    for i, value in enumerate(output_row):
        output_sheet.cell(row=output_sheet.max_row + 1, column=i + 1, value=value)

# Save the workbook
wb.save('output.xlsx')
