from openpyxl import load_workbook

# Load the workbook and select the active sheet
wb = load_workbook('input.xlsx')
ws = wb.active

# Initialize a dictionary to store root words and their corresponding search volumes
root_volume = {}

# Populate the root_volume dictionary with data from columns D and B (rows 2 to 5)
for row in ws.iter_rows(min_row=2, max_row=5, min_col=4, max_col=5):
    root = row[0].value
    volume = row[1].value
    if root:
        root_volume[root] = volume

# Initialize a dictionary to store the sum of search volumes for each root word
root_sum = {root: 0 for root in root_volume}

# Iterate through column A (rows 2 to 6) to find matches in root_volume
for row in ws.iter_rows(min_row=2, max_row=6, min_col=1):
    keyword = row[0].value
    if keyword:
        # Check if the keyword is a complete word in any root
        for root in root_volume:
            if keyword == root:
                root_sum[root] += root_volume[root]
                break

# Write the computed sums into column E (rows 2 to 5)
for i, (root, total) in enumerate(root_sum.items()):
    ws[f'E{i+2}'] = total

# Save the workbook as output.xlsx
wb.save('output.xlsx')
